9	import type {
10	  BaseSelection,
11	  LexicalNode,
12	  NodeKey,
13	  NodeMap,
14	  Point,
15	} from 'lexical';
16	
17	import {createDOMRange, createRectsFromDOMRange} from '@lexical/selection';
18	import {
19	  $getNodeByKey,
20	  $getSelection,
21	  $isElementNode,
22	  $isLineBreakNode,
23	  $isRangeSelection,
24	  $isTextNode,
25	} from 'lexical';
26	import invariant from 'shared/invariant';
27	import {
28	  AbsolutePosition,
29	  compareRelativePositions,
30	  createAbsolutePositionFromRelativePosition,
31	  createRelativePositionFromTypeIndex,
32	  RelativePosition,
33	  XmlElement,
34	  XmlText,
35	} from 'yjs';
36	
37	import {Provider, UserState} from '.';
38	import {
39	  AnyBinding,
40	  type BaseBinding,
41	  type Binding,
42	  type BindingV2,
43	  isBindingV1,
44	} from './Bindings';
45	import {CollabDecoratorNode} from './CollabDecoratorNode';
46	import {CollabElementNode} from './CollabElementNode';
47	import {CollabLineBreakNode} from './CollabLineBreakNode';
48	import {CollabTextNode} from './CollabTextNode';
49	import {CollabV2Mapping} from './CollabV2Mapping';
50	import {getPositionFromElementAndOffset} from './Utils';
51	
52	export type CursorSelection = {
53	  anchor: {
54	    key: NodeKey;
55	    offset: number;
56	  };
57	  caret: HTMLElement;
58	  color: string;
59	  focus: {
60	    key: NodeKey;
61	    offset: number;
62	  };
63	  name: HTMLSpanElement;
64	  selections: Array<HTMLElement>;
65	};
66	export type Cursor = {
67	  color: string;
68	  name: string;
69	  selection: null | CursorSelection;
70	};
71	
72	function createRelativePosition(
73	  point: Point,
74	  binding: Binding,
75	): null | RelativePosition {
76	  const collabNodeMap = binding.collabNodeMap;
77	  const collabNode = collabNodeMap.get(point.key);
78	
79	  if (collabNode === undefined) {
80	    return null;
81	  }
82	
83	  let offset = point.offset;
84	  let sharedType = collabNode.getSharedType();
85	
86	  if (collabNode instanceof CollabTextNode) {
87	    sharedType = collabNode._parent._xmlText;
88	    const currentOffset = collabNode.getOffset();
89	
90	    if (currentOffset === -1) {
91	      return null;
92	    }
93	
94	    offset = currentOffset + 1 + offset;
95	  } else if (
96	    collabNode instanceof CollabElementNode &&
97	    point.type === 'element'
98	  ) {
99	    const parentCollabNode = collabNode._parent;
100	
101	    if (parentCollabNode === null) {
102	      return null;
103	    }
104	
105	    const currentOffset = collabNode.getOffset();
106	
107	    if (currentOffset === -1) {
108	      return null;
109	    }
110	
111	    sharedType = parentCollabNode._xmlText;
112	    offset = currentOffset + offset;
113	  }
114	
115	  return createRelativePositionFromTypeIndex(sharedType, offset);
116	}
117	
118	function createRelativePositionV2(
119	  point: Point,
120	  binding: BindingV2,
121	): null | RelativePosition {
122	  const {mapping} = binding;
123	  const {offset} = point;
124	  const node = point.getNode();
125	  const yType = mapping.getSharedType(node);
126	  if (yType === undefined) {
127	    return null;
128	  }
129	  if (point.type === 'text') {
130	    invariant($isTextNode(node), 'Text point must be a text node');
131	    let prevSibling = node.getPreviousSibling();
132	    let adjustedOffset = offset;
133	    while ($isTextNode(prevSibling)) {
134	      adjustedOffset += prevSibling.getTextContentSize();
135	      prevSibling = prevSibling.getPreviousSibling();
136	    }
137	    return createRelativePositionFromTypeIndex(yType, adjustedOffset);
138	  } else if (point.type === 'element') {
139	    invariant($isElementNode(node), 'Element point must be an element node');
140	    let i = 0;
141	    let child = node.getFirstChild();
142	    while (child !== null && i < offset) {
143	      if ($isTextNode(child)) {
144	        let nextSibling = child.getNextSibling();
145	        while ($isTextNode(nextSibling)) {
146	          nextSibling = nextSibling.getNextSibling();
147	        }
148	      }
149	      i++;
150	      child = child.getNextSibling();
151	    }
152	    return createRelativePositionFromTypeIndex(yType, i);
153	  }
154	  return null;
155	}
156	
157	function createAbsolutePosition(
158	  relativePosition: RelativePosition,
159	  binding: BaseBinding,
160	): AbsolutePosition | null {
161	  return createAbsolutePositionFromRelativePosition(
162	    relativePosition,
163	    binding.doc,
164	  );
165	}
166	
167	function shouldUpdatePosition(
168	  currentPos: RelativePosition | null | undefined,
169	  pos: RelativePosition | null | undefined,
170	): boolean {
171	  if (currentPos == null) {
172	    if (pos != null) {
173	      return true;
174	    }
175	  } else if (pos == null || !compareRelativePositions(currentPos, pos)) {
176	    return true;
177	  }
178	
179	  return false;
180	}
181	
182	function createCursor(name: string, color: string): Cursor {
183	  return {
184	    color: color,
185	    name: name,
186	    selection: null,
187	  };
188	}
189	
190	function destroySelection(binding: BaseBinding, selection: CursorSelection) {
191	  const cursorsContainer = binding.cursorsContainer;
192	
193	  if (cursorsContainer !== null) {
194	    const selections = selection.selections;
195	    const selectionsLength = selections.length;
196	
197	    for (let i = 0; i < selectionsLength; i++) {
198	      cursorsContainer.removeChild(selections[i]);
199	    }
200	  }
201	}
202	
203	function destroyCursor(binding: BaseBinding, cursor: Cursor) {
204	  const selection = cursor.selection;
205	
206	  if (selection !== null) {
207	    destroySelection(binding, selection);
208	  }
209	}
210	
211	function createCursorSelection(
212	  cursor: Cursor,
213	  anchorKey: NodeKey,
214	  anchorOffset: number,
215	  focusKey: NodeKey,
216	  focusOffset: number,
217	): CursorSelection {
218	  const color = cursor.color;
219	  const caret = document.createElement('span');
220	  caret.style.cssText = `position:absolute;top:0;bottom:0;right:-1px;width:1px;background-color:${color};z-index:10;`;
221	  const name = document.createElement('span');
222	  name.textContent = cursor.name;
223	  name.style.cssText = `position:absolute;left:-2px;top:-16px;background-color:${color};color:#fff;line-height:12px;font-size:12px;padding:2px;font-family:Arial;font-weight:bold;white-space:nowrap;`;
224	  caret.appendChild(name);
225	  return {
226	    anchor: {
227	      key: anchorKey,
228	      offset: anchorOffset,
229	    },
230	    caret,
231	    color,
232	    focus: {
233	      key: focusKey,
234	      offset: focusOffset,
235	    },
236	    name,
237	    selections: [],
238	  };
239	}
240	
241	function updateCursor(
242	  binding: BaseBinding,
243	  cursor: Cursor,
244	  nextSelection: null | CursorSelection,
245	  nodeMap: NodeMap,
246	): void {
247	  const editor = binding.editor;
248	  const rootElement = editor.getRootElement();
249	  const cursorsContainer = binding.cursorsContainer;
250	
251	  if (cursorsContainer === null || rootElement === null) {
252	    return;
253	  }
254	
255	  const cursorsContainerOffsetParent = cursorsContainer.offsetParent;
256	  if (cursorsContainerOffsetParent === null) {
257	    return;
258	  }
259	
260	  const containerRect = cursorsContainerOffsetParent.getBoundingClientRect();
261	  const prevSelection = cursor.selection;
262	
263	  if (nextSelection === null) {
264	    if (prevSelection === null) {
265	      return;
266	    } else {
267	      cursor.selection = null;
268	      destroySelection(binding, prevSelection);
269	      return;
270	    }
271	  } else {
272	    cursor.selection = nextSelection;
273	  }
274	
275	  const caret = nextSelection.caret;
276	  const color = nextSelection.color;
277	  const selections = nextSelection.selections;
278	  const anchor = nextSelection.anchor;
279	  const focus = nextSelection.focus;
280	  const anchorKey = anchor.key;
281	  const focusKey = focus.key;
282	  const anchorNode = nodeMap.get(anchorKey);
283	  const focusNode = nodeMap.get(focusKey);
284	
285	  if (anchorNode == null || focusNode == null) {
286	    return;
287	  }
288	  let selectionRects: Array<DOMRect>;
289	
290	  // In the case of a collapsed selection on a linebreak, we need
291	  // to improvise as the browser will return nothing here as <br>
292	  // apparently take up no visual space :/
293	  // This won't work in all cases, but it's better than just showing
294	  // nothing all the time.
295	  if (anchorNode === focusNode && $isLineBreakNode(anchorNode)) {
296	    const brRect = (
297	      editor.getElementByKey(anchorKey) as HTMLElement
298	    ).getBoundingClientRect();
299	    selectionRects = [brRect];
300	  } else {
301	    const range = createDOMRange(
302	      editor,
303	      anchorNode,
304	      anchor.offset,
305	      focusNode,
306	      focus.offset,
307	    );
308	
309	    if (range === null) {
310	      return;
311	    }
312	    selectionRects = createRectsFromDOMRange(editor, range);
313	  }
314	
315	  const selectionsLength = selections.length;
316	  const selectionRectsLength = selectionRects.length;
317	
318	  for (let i = 0; i < selectionRectsLength; i++) {
319	    const selectionRect = selectionRects[i];
320	    let selection = selections[i];
321	
322	    if (selection === undefined) {
323	      selection = document.createElement('span');
324	      selections[i] = selection;
325	      const selectionBg = document.createElement('span');
326	      selection.appendChild(selectionBg);
327	      cursorsContainer.appendChild(selection);
328	    }
329	
330	    const top = selectionRect.top - containerRect.top;
331	    const left = selectionRect.left - containerRect.left;
332	    const style = `position:absolute;top:${top}px;left:${left}px;height:${selectionRect.height}px;width:${selectionRect.width}px;pointer-events:none;z-index:5;`;
333	    selection.style.cssText = style;
334	
335	    (selection.firstChild as HTMLSpanElement).style.cssText =
336	      `${style}left:0;top:0;background-color:${color};opacity:0.3;`;
337	
338	    if (i === selectionRectsLength - 1) {
339	      if (caret.parentNode !== selection) {
340	        selection.appendChild(caret);
341	      }
342	    }
343	  }
344	
345	  for (let i = selectionsLength - 1; i >= selectionRectsLength; i--) {
346	    const selection = selections[i];
347	    cursorsContainer.removeChild(selection);
348	    selections.pop();
349	  }
350	}
351	
352	type AnyCollabNode =
353	  | CollabDecoratorNode
354	  | CollabElementNode
355	  | CollabTextNode
356	  | CollabLineBreakNode;
357	
358	/**
359	 * @deprecated Use `$getAnchorAndFocusForUserState` instead.
360	 */
361	export function getAnchorAndFocusCollabNodesForUserState(
362	  binding: Binding,
363	  userState: UserState,
364	) {
365	  const {anchorPos, focusPos} = userState;
366	  let anchorCollabNode: AnyCollabNode | null = null;
367	  let anchorOffset = 0;
368	  let focusCollabNode: AnyCollabNode | null = null;
369	  let focusOffset = 0;
370	
371	  if (anchorPos !== null && focusPos !== null) {
372	    const anchorAbsPos = createAbsolutePosition(anchorPos, binding);
373	    const focusAbsPos = createAbsolutePosition(focusPos, binding);
374	
375	    if (anchorAbsPos !== null && focusAbsPos !== null) {
376	      [anchorCollabNode, anchorOffset] = getCollabNodeAndOffset(
377	        anchorAbsPos.type,
378	        anchorAbsPos.index,
379	      );
380	      [focusCollabNode, focusOffset] = getCollabNodeAndOffset(
381	        focusAbsPos.type,
382	        focusAbsPos.index,
383	      );
384	    }
385	  }
386	
387	  return {
388	    anchorCollabNode,
389	    anchorOffset,
390	    focusCollabNode,
391	    focusOffset,
392	  };
393	}
394	
395	export function $getAnchorAndFocusForUserState(
396	  binding: AnyBinding,
397	  userState: UserState,
398	): {
399	  anchorKey: NodeKey | null;
400	  anchorOffset: number;
401	  focusKey: NodeKey | null;
402	  focusOffset: number;
403	} {
404	  const {anchorPos, focusPos} = userState;
405	  const anchorAbsPos = anchorPos
406	    ? createAbsolutePosition(anchorPos, binding)
407	    : null;
408	  const focusAbsPos = focusPos
409	    ? createAbsolutePosition(focusPos, binding)
410	    : null;
411	
412	  if (anchorAbsPos === null || focusAbsPos === null) {
413	    return {
414	      anchorKey: null,
415	      anchorOffset: 0,
416	      focusKey: null,
417	      focusOffset: 0,
418	    };
419	  }
420	
421	  if (isBindingV1(binding)) {
422	    const [anchorCollabNode, anchorOffset] = getCollabNodeAndOffset(
423	      anchorAbsPos.type,
424	      anchorAbsPos.index,
425	    );
426	    const [focusCollabNode, focusOffset] = getCollabNodeAndOffset(
427	      focusAbsPos.type,
428	      focusAbsPos.index,
429	    );
430	    return {
431	      anchorKey: anchorCollabNode !== null ? anchorCollabNode.getKey() : null,
432	      anchorOffset,
433	      focusKey: focusCollabNode !== null ? focusCollabNode.getKey() : null,
434	      focusOffset,
435	    };
436	  }
437	
438	  let [anchorNode, anchorOffset] = $getNodeAndOffsetV2(
439	    binding.mapping,
440	    anchorAbsPos,
441	  );
442	  let [focusNode, focusOffset] = $getNodeAndOffsetV2(
443	    binding.mapping,
444	    focusAbsPos,
445	  );
446	  // For a non-collapsed selection, if the start of the selection is as the end of a text node,
447	  // move it to the beginning of the next text node (if one exists).
448	  if (
449	    focusNode &&
450	    anchorNode &&
451	    (focusNode !== anchorNode || focusOffset !== anchorOffset)
452	  ) {
453	    const isBackwards = focusNode.isBefore(anchorNode);
454	    const startNode = isBackwards ? focusNode : anchorNode;
455	    const startOffset = isBackwards ? focusOffset : anchorOffset;
456	    if (
457	      $isTextNode(startNode) &&
458	      $isTextNode(startNode.getNextSibling()) &&
459	      startOffset === startNode.getTextContentSize()
460	    ) {
461	      if (isBackwards) {
462	        focusNode = startNode.getNextSibling();
463	        focusOffset = 0;
464	      } else {
465	        anchorNode = startNode.getNextSibling();
466	        anchorOffset = 0;
467	      }
468	    }
469	  }
470	  return {
471	    anchorKey: anchorNode !== null ? anchorNode.getKey() : null,
472	    anchorOffset,
473	    focusKey: focusNode !== null ? focusNode.getKey() : null,
474	    focusOffset,
475	  };
476	}
477	
478	export function $syncLocalCursorPosition(
479	  binding: AnyBinding,
480	  provider: Provider,
481	): void {
482	  const awareness = provider.awareness;
483	  const localState = awareness.getLocalState();
484	
485	  if (localState === null) {
486	    return;
487	  }
488	
489	  const {anchorKey, anchorOffset, focusKey, focusOffset} =
490	    $getAnchorAndFocusForUserState(binding, localState);
491	
492	  if (anchorKey !== null && focusKey !== null) {
493	    const selection = $getSelection();
494	
495	    if (!$isRangeSelection(selection)) {
496	      return;
497	    }
498	
499	    $setPoint(selection.anchor, anchorKey, anchorOffset);
500	    $setPoint(selection.focus, focusKey, focusOffset);
501	  }
502	}
503	
504	function $setPoint(point: Point, key: NodeKey, offset: number): void {
505	  if (point.key !== key || point.offset !== offset) {
506	    let anchorNode = $getNodeByKey(key);
507	    if (
508	      anchorNode !== null &&
509	      !$isElementNode(anchorNode) &&
510	      !$isTextNode(anchorNode)
511	    ) {
512	      const parent = anchorNode.getParentOrThrow();
513	      key = parent.getKey();
514	      offset = anchorNode.getIndexWithinParent();
515	      anchorNode = parent;
516	    }
517	    point.set(key, offset, $isElementNode(anchorNode) ? 'element' : 'text');
518	  }
519	}
520	
521	function getCollabNodeAndOffset(
522	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
523	  sharedType: any,
524	  offset: number,
525	): [null | AnyCollabNode, number] {
526	  const collabNode = sharedType._collabNode;
527	
528	  if (collabNode === undefined) {
529	    return [null, 0];
530	  }
531	
532	  if (collabNode instanceof CollabElementNode) {
533	    const {node, offset: collabNodeOffset} = getPositionFromElementAndOffset(
534	      collabNode,
535	      offset,
536	      true,
537	    );
538	
539	    if (node === null) {
540	      return [collabNode, 0];
541	    } else {
542	      return [node, collabNodeOffset];
543	    }
544	  }
545	
546	  return [null, 0];
547	}
548	
549	function $getNodeAndOffsetV2(
550	  mapping: CollabV2Mapping,
551	  absolutePosition: AbsolutePosition,
552	): [null | LexicalNode, number] {
553	  const yType = absolutePosition.type as XmlElement | XmlText;
554	  const yOffset = absolutePosition.index;
555	  if (yType instanceof XmlElement) {
556	    const node = mapping.get(yType);
557	    if (node === undefined) {
558	      return [null, 0];
559	    }
560	    if (!$isElementNode(node)) {
561	      return [node, yOffset];
562	    }
563	    let remainingYOffset = yOffset;
564	    let lexicalOffset = 0;
565	    const children = node.getChildren();
566	    while (remainingYOffset > 0 && lexicalOffset < children.length) {
567	      const child = children[lexicalOffset];
568	      remainingYOffset -= 1;
569	      lexicalOffset += 1;
570	      if ($isTextNode(child)) {
571	        while (
572	          lexicalOffset < children.length &&
573	          $isTextNode(children[lexicalOffset])
574	        ) {
575	          lexicalOffset += 1;
576	        }
577	      }
578	    }
579	    return [node, lexicalOffset];
580	  } else {
581	    const nodes = mapping.get(yType);
582	    if (nodes === undefined) {
583	      return [null, 0];
584	    }
585	    let i = 0;
586	    let adjustedOffset = yOffset;
587	    while (
588	      adjustedOffset > nodes[i].getTextContentSize() &&
589	      i + 1 < nodes.length
590	    ) {
591	      adjustedOffset -= nodes[i].getTextContentSize();
592	      i++;
593	    }
594	    const textNode = nodes[i];
595	    return [textNode, Math.min(adjustedOffset, textNode.getTextContentSize())];
596	  }
597	}
598	
599	export type SyncCursorPositionsFn = (
600	  binding: AnyBinding,
601	  provider: Provider,
602	  options?: SyncCursorPositionsOptions,
603	) => void;
604	
605	export type SyncCursorPositionsOptions = {
606	  getAwarenessStates?: (
607	    binding: BaseBinding,
608	    provider: Provider,
609	  ) => Map<number, UserState>;
610	};
611	
612	function getAwarenessStatesDefault(
613	  _binding: BaseBinding,
614	  provider: Provider,
615	): Map<number, UserState> {
616	  return provider.awareness.getStates();
617	}
618	
619	export function syncCursorPositions(
620	  binding: AnyBinding,
621	  provider: Provider,
622	  options?: SyncCursorPositionsOptions,
623	): void {
624	  const {getAwarenessStates = getAwarenessStatesDefault} = options ?? {};
625	  const awarenessStates = Array.from(getAwarenessStates(binding, provider));
626	  const localClientID = binding.clientID;
627	  const cursors = binding.cursors;
628	  const editor = binding.editor;
629	  const nodeMap = editor._editorState._nodeMap;
630	  const visitedClientIDs = new Set();
631	
632	  for (let i = 0; i < awarenessStates.length; i++) {
633	    const awarenessState = awarenessStates[i];
634	    const [clientID, awareness] = awarenessState;
635	
636	    if (clientID !== 0 && clientID !== localClientID) {
637	      visitedClientIDs.add(clientID);
638	      const {name, color, focusing} = awareness;
639	      let selection = null;
640	
641	      let cursor = cursors.get(clientID);
642	
643	      if (cursor === undefined) {
644	        cursor = createCursor(name, color);
645	        cursors.set(clientID, cursor);
646	      }
647	
648	      if (focusing) {
649	        const {anchorKey, anchorOffset, focusKey, focusOffset} = editor.read(
650	          () => $getAnchorAndFocusForUserState(binding, awareness),
651	        );
652	
653	        if (anchorKey !== null && focusKey !== null) {
654	          selection = cursor.selection;
655	
656	          if (selection === null) {
657	            selection = createCursorSelection(
658	              cursor,
659	              anchorKey,
660	              anchorOffset,
661	              focusKey,
662	              focusOffset,
663	            );
664	          }
665	        }
666	      }
667	
668	      updateCursor(binding, cursor, selection, nodeMap);
669	    }
670	  }
671	
672	  const allClientIDs = Array.from(cursors.keys());
673	
674	  for (let i = 0; i < allClientIDs.length; i++) {
675	    const clientID = allClientIDs[i];
676	
677	    if (!visitedClientIDs.has(clientID)) {
678	      const cursor = cursors.get(clientID);
679	
680	      if (cursor !== undefined) {
681	        destroyCursor(binding, cursor);
682	        cursors.delete(clientID);
683	      }
684	    }
685	  }
686	}
687	
688	export function syncLexicalSelectionToYjs(
689	  binding: AnyBinding,
690	  provider: Provider,
691	  prevSelection: null | BaseSelection,
692	  nextSelection: null | BaseSelection,
693	): void {
694	  const awareness = provider.awareness;
695	  const localState = awareness.getLocalState();
696	
697	  if (localState === null) {
698	    return;
699	  }
700	
701	  const {
702	    anchorPos: currentAnchorPos,
703	    focusPos: currentFocusPos,
704	    name,
705	    color,
706	    focusing,
707	    awarenessData,
708	  } = localState;
709	  let anchorPos = null;
710	  let focusPos = null;
711	
712	  if (
713	    nextSelection === null ||
714	    (currentAnchorPos !== null && !nextSelection.is(prevSelection))
715	  ) {
716	    if (prevSelection === null) {
717	      return;
718	    }
719	  }
720	
721	  if ($isRangeSelection(nextSelection)) {
722	    if (isBindingV1(binding)) {
723	      anchorPos = createRelativePosition(nextSelection.anchor, binding);
724	      focusPos = createRelativePosition(nextSelection.focus, binding);
725	    } else {
726	      anchorPos = createRelativePositionV2(nextSelection.anchor, binding);
727	      focusPos = createRelativePositionV2(nextSelection.focus, binding);
728	    }
729	  }
730	
731	  if (
732	    shouldUpdatePosition(currentAnchorPos, anchorPos) ||
733	    shouldUpdatePosition(currentFocusPos, focusPos)
734	  ) {
735	    awareness.setLocalState({
736	      ...localState,
737	      anchorPos,
738	      awarenessData,
739	      color,
740	      focusPos,
741	      focusing,
742	      name,
743	    });
744	  }
745	}
