37	import {$createCollabElementNode, CollabElementNode} from './CollabElementNode';
38	import {
39	  $createCollabLineBreakNode,
40	  CollabLineBreakNode,
41	} from './CollabLineBreakNode';
42	import {$createCollabTextNode, CollabTextNode} from './CollabTextNode';
43	
44	const baseExcludedProperties = new Set<string>([
45	  '__key',
46	  '__parent',
47	  '__next',
48	  '__prev',
49	  '__state',
50	]);
51	const elementExcludedProperties = new Set<string>([
52	  '__first',
53	  '__last',
54	  '__size',
55	]);
56	const rootExcludedProperties = new Set<string>(['__cachedText']);
57	const textExcludedProperties = new Set<string>(['__text']);
58	
59	function isExcludedProperty(
60	  name: string,
61	  node: LexicalNode,
62	  binding: BaseBinding,
63	): boolean {
64	  if (
65	    baseExcludedProperties.has(name) ||
66	    typeof (node as unknown as Record<string, unknown>)[name] === 'function'
67	  ) {
68	    return true;
69	  }
70	
71	  if ($isTextNode(node)) {
72	    if (textExcludedProperties.has(name)) {
73	      return true;
74	    }
75	  } else if ($isElementNode(node)) {
76	    if (
77	      elementExcludedProperties.has(name) ||
78	      ($isRootNode(node) && rootExcludedProperties.has(name))
79	    ) {
80	      return true;
81	    }
82	  }
83	
84	  const nodeKlass = node.constructor;
85	  const excludedProperties = binding.excludedProperties.get(nodeKlass);
86	  return excludedProperties != null && excludedProperties.has(name);
87	}
88	
89	export function initializeNodeProperties(binding: BaseBinding): void {
90	  const {editor, nodeProperties} = binding;
91	  editor.update(() => {
92	    editor._nodes.forEach((nodeInfo) => {
93	      const node = new nodeInfo.klass();
94	      const defaultProperties: {[property: string]: unknown} = {};
95	      for (const [property, value] of Object.entries(node)) {
96	        if (!isExcludedProperty(property, node, binding)) {
97	          defaultProperties[property] = value;
98	        }
99	      }
100	      nodeProperties.set(node.__type, Object.freeze(defaultProperties));
101	    });
102	  });
103	}
104	
105	export function getDefaultNodeProperties(
106	  node: LexicalNode,
107	  binding: BaseBinding,
108	): {[property: string]: unknown} {
109	  const type = node.__type;
110	  const {nodeProperties} = binding;
111	  const properties = nodeProperties.get(type);
112	  invariant(
113	    properties !== undefined,
114	    'Node properties for %s not initialized for sync',
115	    type,
116	  );
117	  return properties;
118	}
119	
120	export function getIndexOfYjsNode(
121	  yjsParentNode: YjsNode,
122	  yjsNode: YjsNode,
123	): number {
124	  let node = yjsParentNode.firstChild;
125	  let i = -1;
126	
127	  if (node === null) {
128	    return -1;
129	  }
130	
131	  do {
132	    i++;
133	
134	    if (node === yjsNode) {
135	      return i;
136	    }
137	
138	    // @ts-expect-error Sibling exists but type is not available from YJS.
139	    node = node.nextSibling;
140	
141	    if (node === null) {
142	      return -1;
143	    }
144	  } while (node !== null);
145	
146	  return i;
147	}
148	
149	export function $createCollabNodeFromLexicalNode(
150	  binding: Binding,
151	  lexicalNode: LexicalNode,
152	  parent: CollabElementNode,
153	):
154	  | CollabElementNode
155	  | CollabTextNode
156	  | CollabLineBreakNode
157	  | CollabDecoratorNode {
158	  const nodeType = lexicalNode.__type;
159	  let collabNode;
160	
161	  if ($isElementNode(lexicalNode)) {
162	    const xmlText = new XmlText();
163	    collabNode = $createCollabElementNode(xmlText, parent, nodeType);
164	    collabNode.syncPropertiesFromLexical(binding, lexicalNode, null);
165	    collabNode.syncChildrenFromLexical(binding, lexicalNode, null, null, null);
166	  } else if ($isTextNode(lexicalNode)) {
167	    // TODO create a token text node for token, segmented nodes.
168	    const map = new YMap();
169	    collabNode = $createCollabTextNode(
170	      map,
171	      lexicalNode.__text,
172	      parent,
173	      nodeType,
174	    );
175	    collabNode.syncPropertiesAndTextFromLexical(binding, lexicalNode, null);
176	  } else if ($isLineBreakNode(lexicalNode)) {
177	    const map = new YMap();
178	    map.set('__type', 'linebreak');
179	    collabNode = $createCollabLineBreakNode(map, parent);
180	  } else if ($isDecoratorNode(lexicalNode)) {
181	    const xmlElem = new XmlElement();
182	    collabNode = $createCollabDecoratorNode(xmlElem, parent, nodeType);
183	    collabNode.syncPropertiesFromLexical(binding, lexicalNode, null);
184	  } else {
185	    invariant(false, 'Expected text, element, decorator, or linebreak node');
186	  }
187	
188	  collabNode._key = lexicalNode.__key;
189	  return collabNode;
190	}
191	
192	export function getNodeTypeFromSharedType(
193	  sharedType: XmlText | YMap<unknown> | XmlElement,
194	): string | undefined {
195	  const type = sharedTypeGet(sharedType, '__type');
196	  invariant(
197	    typeof type === 'string' || typeof type === 'undefined',
198	    'Expected shared type to include type attribute',
199	  );
200	  return type;
201	}
202	
203	export function $getOrInitCollabNodeFromSharedType(
204	  binding: Binding,
205	  sharedType: XmlText | YMap<unknown> | XmlElement,
206	  parent?: CollabElementNode,
207	):
208	  | CollabElementNode
209	  | CollabTextNode
210	  | CollabLineBreakNode
211	  | CollabDecoratorNode {
212	  const collabNode = sharedType._collabNode;
213	
214	  if (collabNode === undefined) {
215	    const registeredNodes = binding.editor._nodes;
216	    const type = getNodeTypeFromSharedType(sharedType);
217	    invariant(
218	      typeof type === 'string',
219	      'Expected shared type to include type attribute',
220	    );
221	    const nodeInfo = registeredNodes.get(type);
222	    invariant(nodeInfo !== undefined, 'Node %s is not registered', type);
223	
224	    const sharedParent = sharedType.parent;
225	    const targetParent =
226	      parent === undefined && sharedParent !== null
227	        ? $getOrInitCollabNodeFromSharedType(
228	            binding,
229	            sharedParent as XmlText | YMap<unknown> | XmlElement,
230	          )
231	        : parent || null;
232	
233	    invariant(
234	      targetParent instanceof CollabElementNode,
235	      'Expected parent to be a collab element node',
236	    );
237	
238	    if (sharedType instanceof XmlText) {
239	      return $createCollabElementNode(sharedType, targetParent, type);
240	    } else if (sharedType instanceof YMap) {
241	      if (type === 'linebreak') {
242	        return $createCollabLineBreakNode(sharedType, targetParent);
243	      }
244	      return $createCollabTextNode(sharedType, '', targetParent, type);
245	    } else if (sharedType instanceof XmlElement) {
246	      return $createCollabDecoratorNode(sharedType, targetParent, type);
247	    }
248	  }
249	
250	  return collabNode;
251	}
252	
253	export function createLexicalNodeFromCollabNode(
254	  binding: Binding,
255	  collabNode:
256	    | CollabElementNode
257	    | CollabTextNode
258	    | CollabDecoratorNode
259	    | CollabLineBreakNode,
260	  parentKey: NodeKey,
261	): LexicalNode {
262	  const type = collabNode.getType();
263	  const registeredNodes = binding.editor._nodes;
264	  const nodeInfo = registeredNodes.get(type);
265	  invariant(nodeInfo !== undefined, 'Node %s is not registered', type);
266	  const lexicalNode:
267	    | DecoratorNode<unknown>
268	    | TextNode
269	    | ElementNode
270	    | LexicalNode = new nodeInfo.klass();
271	  lexicalNode.__parent = parentKey;
272	  collabNode._key = lexicalNode.__key;
273	
274	  if (collabNode instanceof CollabElementNode) {
275	    const xmlText = collabNode._xmlText;
276	    collabNode.syncPropertiesFromYjs(binding, null);
277	    collabNode.applyChildrenYjsDelta(binding, xmlText.toDelta());
278	    collabNode.syncChildrenFromYjs(binding);
279	  } else if (collabNode instanceof CollabTextNode) {
280	    collabNode.syncPropertiesAndTextFromYjs(binding, null);
281	  } else if (collabNode instanceof CollabDecoratorNode) {
282	    collabNode.syncPropertiesFromYjs(binding, null);
283	  }
284	
285	  binding.collabNodeMap.set(lexicalNode.__key, collabNode);
286	  return lexicalNode;
287	}
288	
289	export function $syncPropertiesFromYjs(
290	  binding: BaseBinding,
291	  sharedType:
292	    | XmlText
293	    | YMap<unknown>
294	    | XmlElement
295	    // v2
296	    | Record<string, unknown>,
297	  lexicalNode: LexicalNode,
298	  keysChanged: null | Set<string>,
299	): void {
300	  const properties =
301	    keysChanged === null
302	      ? sharedType instanceof YMap
303	        ? Array.from(sharedType.keys())
304	        : sharedType instanceof XmlText || sharedType instanceof XmlElement
305	          ? Object.keys(sharedType.getAttributes())
306	          : Object.keys(sharedType)
307	      : Array.from(keysChanged);
308	  let writableNode: LexicalNode | undefined;
309	
310	  for (let i = 0; i < properties.length; i++) {
311	    const property = properties[i];
312	    if (isExcludedProperty(property, lexicalNode, binding)) {
313	      if (property === '__state' && isBindingV1(binding)) {
314	        if (!writableNode) {
315	          writableNode = lexicalNode.getWritable();
316	        }
317	        $syncNodeStateToLexical(sharedType, writableNode);
318	      }
319	      continue;
320	    }
321	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
322	    const prevValue = (lexicalNode as any)[property];
323	    let nextValue = sharedTypeGet(sharedType, property);
324	
325	    if (prevValue !== nextValue) {
326	      if (nextValue instanceof Doc) {
327	        const yjsDocMap = binding.docMap;
328	
329	        if (prevValue instanceof Doc) {
330	          yjsDocMap.delete(prevValue.guid);
331	        }
332	
333	        const nestedEditor = createEditor();
334	        const key = nextValue.guid;
335	        nestedEditor._key = key;
336	        yjsDocMap.set(key, nextValue);
337	
338	        nextValue = nestedEditor;
339	      }
340	
341	      if (writableNode === undefined) {
342	        writableNode = lexicalNode.getWritable();
343	      }
344	
345	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
346	      writableNode[property as keyof typeof writableNode] = nextValue as any;
347	    }
348	  }
349	}
350	
351	function sharedTypeGet(
352	  sharedType: XmlText | YMap<unknown> | XmlElement | Record<string, unknown>,
353	  property: string,
354	): unknown {
355	  if (sharedType instanceof YMap) {
356	    return sharedType.get(property);
357	  } else if (
358	    sharedType instanceof XmlText ||
359	    sharedType instanceof XmlElement
360	  ) {
361	    return sharedType.getAttribute(property);
362	  } else {
363	    return sharedType[property];
364	  }
365	}
366	
367	function sharedTypeSet(
368	  sharedType: XmlText | YMap<unknown> | XmlElement,
369	  property: string,
370	  nextValue: unknown,
371	): void {
372	  if (sharedType instanceof YMap) {
373	    sharedType.set(property, nextValue);
374	  } else {
375	    sharedType.setAttribute(property, nextValue as string);
376	  }
377	}
378	
379	function $syncNodeStateToLexical(
380	  sharedType: XmlText | YMap<unknown> | XmlElement | Record<string, unknown>,
381	  lexicalNode: LexicalNode,
382	): void {
383	  const existingState = sharedTypeGet(sharedType, '__state');
384	  if (!(existingState instanceof YMap)) {
385	    return;
386	  }
387	  // This should only called when creating the node initially,
388	  // incremental updates to state come in through YMapEvent
389	  // with the __state as the target.
390	  $getWritableNodeState(lexicalNode).updateFromJSON(existingState.toJSON());
391	}
392	
393	function syncNodeStateFromLexical(
394	  binding: Binding,
395	  sharedType: XmlText | YMap<unknown> | XmlElement,
396	  prevLexicalNode: null | LexicalNode,
397	  nextLexicalNode: LexicalNode,
398	): void {
399	  const nextState = nextLexicalNode.__state;
400	  const existingState = sharedTypeGet(sharedType, '__state');
401	  if (!nextState) {
402	    return;
403	  }
404	  const [unknown, known] = nextState.getInternalState();
405	  const prevState = prevLexicalNode && prevLexicalNode.__state;
406	  const stateMap: YMap<unknown> =
407	    existingState instanceof YMap ? existingState : new YMap();
408	  if (prevState === nextState) {
409	    return;
410	  }
411	  const [prevUnknown, prevKnown] =
412	    prevState && stateMap.doc
413	      ? prevState.getInternalState()
414	      : [undefined, new Map()];
415	  if (unknown) {
416	    for (const [k, v] of Object.entries(unknown)) {
417	      if (prevUnknown && v !== prevUnknown[k]) {
418	        stateMap.set(k, v);
419	      }
420	    }
421	  }
422	  for (const [stateConfig, v] of known) {
423	    if (prevKnown.get(stateConfig) !== v) {
424	      stateMap.set(stateConfig.key, stateConfig.unparse(v));
425	    }
426	  }
427	  if (!existingState) {
428	    sharedTypeSet(sharedType, '__state', stateMap);
429	  }
430	}
431	
432	export function syncPropertiesFromLexical(
433	  binding: Binding,
434	  sharedType: XmlText | YMap<unknown> | XmlElement,
435	  prevLexicalNode: null | LexicalNode,
436	  nextLexicalNode: LexicalNode,
437	): void {
438	  const properties = Object.keys(
439	    getDefaultNodeProperties(nextLexicalNode, binding),
440	  );
441	
442	  const EditorClass = binding.editor.constructor;
443	
444	  syncNodeStateFromLexical(
445	    binding,
446	    sharedType,
447	    prevLexicalNode,
448	    nextLexicalNode,
449	  );
450	  for (let i = 0; i < properties.length; i++) {
451	    const property = properties[i];
452	    const prevValue =
453	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
454	      prevLexicalNode === null ? undefined : (prevLexicalNode as any)[property];
455	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
456	    let nextValue = (nextLexicalNode as any)[property];
457	
458	    if (prevValue !== nextValue) {
459	      if (nextValue instanceof EditorClass) {
460	        const yjsDocMap = binding.docMap;
461	        let prevDoc;
462	
463	        if (prevValue instanceof EditorClass) {
464	          const prevKey = prevValue._key;
465	          prevDoc = yjsDocMap.get(prevKey);
466	          yjsDocMap.delete(prevKey);
467	        }
468	
469	        // If we already have a document, use it.
470	        const doc = prevDoc || new Doc();
471	        const key = doc.guid;
472	        nextValue._key = key;
473	        yjsDocMap.set(key, doc);
474	        nextValue = doc;
475	        // Mark the node dirty as we've assigned a new key to it
476	        binding.editor.update(() => {
477	          nextLexicalNode.markDirty();
478	        });
479	      }
480	
481	      sharedTypeSet(sharedType, property, nextValue);
482	    }
483	  }
484	}
485	
486	export function spliceString(
487	  str: string,
488	  index: number,
489	  delCount: number,
490	  newText: string,
491	): string {
492	  return str.slice(0, index) + newText + str.slice(index + delCount);
493	}
494	
495	export function getPositionFromElementAndOffset(
496	  node: CollabElementNode,
497	  offset: number,
498	  boundaryIsEdge: boolean,
499	): {
500	  length: number;
501	  node:
502	    | CollabElementNode
503	    | CollabTextNode
504	    | CollabDecoratorNode
505	    | CollabLineBreakNode
506	    | null;
507	  nodeIndex: number;
508	  offset: number;
509	} {
510	  let index = 0;
511	  let i = 0;
512	  const children = node._children;
513	  const childrenLength = children.length;
514	
515	  for (; i < childrenLength; i++) {
516	    const child = children[i];
517	    const childOffset = index;
518	    const size = child.getSize();
519	    index += size;
520	    const exceedsBoundary = boundaryIsEdge ? index >= offset : index > offset;
521	
522	    if (exceedsBoundary && child instanceof CollabTextNode) {
523	      let textOffset = offset - childOffset - 1;
524	
525	      if (textOffset < 0) {
526	        textOffset = 0;
527	      }
528	
529	      const diffLength = index - offset;
530	      return {
531	        length: diffLength,
532	        node: child,
533	        nodeIndex: i,
534	        offset: textOffset,
535	      };
536	    }
537	
538	    if (index > offset) {
539	      return {
540	        length: 0,
541	        node: child,
542	        nodeIndex: i,
543	        offset: childOffset,
544	      };
545	    } else if (i === childrenLength - 1) {
546	      return {
547	        length: 0,
548	        node: null,
549	        nodeIndex: i + 1,
550	        offset: childOffset + 1,
551	      };
552	    }
553	  }
554	
555	  return {
556	    length: 0,
557	    node: null,
558	    nodeIndex: 0,
559	    offset: 0,
560	  };
561	}
562	
563	export function doesSelectionNeedRecovering(
564	  selection: RangeSelection,
565	): boolean {
566	  const anchor = selection.anchor;
567	  const focus = selection.focus;
568	  let recoveryNeeded = false;
569	
570	  try {
571	    const anchorNode = anchor.getNode();
572	    const focusNode = focus.getNode();
573	
574	    if (
575	      // We might have removed a node that no longer exists
576	      !anchorNode.isAttached() ||
577	      !focusNode.isAttached() ||
578	      // If we've split a node, then the offset might not be right
579	      ($isTextNode(anchorNode) &&
580	        anchor.offset > anchorNode.getTextContentSize()) ||
581	      ($isTextNode(focusNode) && focus.offset > focusNode.getTextContentSize())
582	    ) {
583	      recoveryNeeded = true;
584	    }
585	  } catch (_e) {
586	    // Sometimes checking nor a node via getNode might trigger
587	    // an error, so we need recovery then too.
588	    recoveryNeeded = true;
589	  }
590	
591	  return recoveryNeeded;
592	}
593	
594	export function syncWithTransaction(
595	  binding: BaseBinding,
596	  fn: () => void,
597	): void {
598	  binding.doc.transact(fn, binding);
599	}
600	
601	export function $moveSelectionToPreviousNode(
602	  anchorNodeKey: string,
603	  currentEditorState: EditorState,
604	) {
605	  const anchorNode = currentEditorState._nodeMap.get(anchorNodeKey);
606	  if (!anchorNode) {
607	    $getRoot().selectStart();
608	    return;
609	  }
610	  // Get previous node
611	  const prevNodeKey = anchorNode.__prev;
612	  let prevNode: ElementNode | null = null;
613	  if (prevNodeKey) {
614	    prevNode = $getNodeByKey(prevNodeKey);
615	  }
616	
617	  // If previous node not found, get parent node
618	  if (prevNode === null && anchorNode.__parent !== null) {
619	    prevNode = $getNodeByKey(anchorNode.__parent);
620	  }
621	  if (prevNode === null) {
622	    $getRoot().selectStart();
623	    return;
624	  }
625	
626	  if (prevNode !== null && prevNode.isAttached()) {
627	    prevNode.selectEnd();
628	    return;
629	  } else {
630	    // If the found node is also deleted, select the next one
631	    $moveSelectionToPreviousNode(prevNode.__key, currentEditorState);
632	  }
633	}
