}, [editor, binding, provider]);

useEffect(() => {
  const {root} = binding;
  const {awareness} = provider;

  if (diffSnapshots) {
    renderSnapshot__EXPERIMENTAL(
      binding,
      diffSnapshots.snapshot,
      diffSnapshots.prevSnapshot,
    );
    return;
  }

  const onYjsTreeChanges: OnYjsTreeChanges = (events, transaction) => {
    const origin = transaction.origin;
    if (origin !== binding) {
      const isFromUndoManger = origin instanceof UndoManager;
      syncYjsChangesToLexicalV2__EXPERIMENTAL(
        binding,
        provider,
        events,
        transaction,
        isFromUndoManger,
      );
    }
  };

  // This updates the local editor state when we receive updates from other clients
  root.observeDeep(onYjsTreeChanges);
  const removeListener = editor.registerUpdateListener(
    ({
      prevEditorState,
      editorState,
      dirtyElements,
      normalizedNodes,
      tags,
    }) => {
      if (!tags.has(SKIP_COLLAB_TAG)) {
        syncLexicalUpdateToYjsV2__EXPERIMENTAL(
          binding,
          provider,
          prevEditorState,
          editorState,
          dirtyElements,
          normalizedNodes,
          tags,
        );
      }
    },
  );

  const onAwarenessUpdate = () => {
    syncCursorPositions(binding, provider);
  };
  awareness.on('update', onAwarenessUpdate);

  return () => {
    root.unobserveDeep(onYjsTreeChanges);
    removeListener();
    awareness.off('update', onAwarenessUpdate);
  };
}, [binding, provider, editor, diffSnapshots]);

useProvider(
  editor,
  provider,
  name,
  color,
  isReloadingDoc,
  awarenessData,
  onBootstrap,
);

