68	export function useYjsCollaboration(
69	  editor: LexicalEditor,
70	  id: string,
71	  provider: Provider,
72	  docMap: Map<string, Doc>,
73	  name: string,
74	  color: string,
75	  shouldBootstrap: boolean,
76	  binding: Binding,
77	  setDoc: React.Dispatch<React.SetStateAction<Doc | undefined>>,
78	  cursorsContainerRef?: CursorsContainerRef,
79	  initialEditorState?: InitialEditorStateType,
80	  awarenessData?: object,
81	  syncCursorPositionsFn: SyncCursorPositionsFn = syncCursorPositions,
82	): JSX.Element {
83	  const isReloadingDoc = useRef(false);
84	
85	  const onBootstrap = useCallback(() => {
86	    const {root} = binding;
87	    if (shouldBootstrap && root.isEmpty() && root._xmlText._length === 0) {
88	      initializeEditor(editor, initialEditorState);
89	    }
90	  }, [binding, editor, initialEditorState, shouldBootstrap]);
91	
92	  useEffect(() => {
93	    const {root} = binding;
94	
95	    const onYjsTreeChanges: OnYjsTreeChanges = (events, transaction) => {
96	      const origin = transaction.origin;
97	      if (origin !== binding) {
98	        const isFromUndoManger = origin instanceof UndoManager;
99	        syncYjsChangesToLexical(
100	          binding,
101	          provider,
102	          events,
103	          isFromUndoManger,
104	          syncCursorPositionsFn,
105	        );
106	      }
107	    };
108	
109	    // This updates the local editor state when we receive updates from other clients
110	    root.getSharedType().observeDeep(onYjsTreeChanges);
111	    const removeListener = editor.registerUpdateListener(
112	      ({
113	        prevEditorState,
114	        editorState,
115	        dirtyLeaves,
116	        dirtyElements,
117	        normalizedNodes,
118	        tags,
119	      }) => {
120	        if (!tags.has(SKIP_COLLAB_TAG)) {
121	          syncLexicalUpdateToYjs(
122	            binding,
123	            provider,
124	            prevEditorState,
125	            editorState,
126	            dirtyElements,
127	            dirtyLeaves,
128	            normalizedNodes,
129	            tags,
130	          );
131	        }
132	      },
133	    );
134	
135	    return () => {
136	      root.getSharedType().unobserveDeep(onYjsTreeChanges);
137	      removeListener();
138	    };
139	  }, [binding, provider, editor, setDoc, docMap, id, syncCursorPositionsFn]);
140	
141	  // Note: 'reload' is not an actual Yjs event type. Included here for legacy support (#1409).
142	  useEffect(() => {
143	    const onProviderDocReload = (ydoc: Doc) => {
144	      clearEditorSkipCollab(editor, binding);
145	      setDoc(ydoc);
146	      docMap.set(id, ydoc);
147	      isReloadingDoc.current = true;
148	    };
149	
150	    const onSync = () => {
151	      isReloadingDoc.current = false;
152	    };
153	
154	    provider.on('reload', onProviderDocReload);
155	    provider.on('sync', onSync);
156	
157	    return () => {
158	      provider.off('reload', onProviderDocReload);
159	      provider.off('sync', onSync);
